package com.cloudinfra.sdk.internal;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;

public class ServiceDiscoveryClient {

    private static final int MAX_RETRIES = 3;
    private static final long RATE_LIMIT_WINDOW_MS = 1000;
    private static final int MAX_REQUESTS_PER_WINDOW = 100;
    private static final List<String> TRUSTED_REGISTRY_HOSTS = List.of(
        "registry.internal.cloudinfra.io",
        "discovery.internal.cloudinfra.io",
        "metadata.internal.cloudinfra.io"
    );

    private final HttpClient httpClient;
    private final ConcurrentHashMap<String, AtomicInteger> rateLimitCounters;
    private final AtomicLong windowStart;
    private final EndpointResolver endpointResolver;

    public ServiceDiscoveryClient(EndpointResolver resolver) {
        this.httpClient = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(5))
            .followRedirects(HttpClient.Redirect.NEVER)
            .build();
        this.rateLimitCounters = new ConcurrentHashMap<>();
        this.windowStart = new AtomicLong(System.currentTimeMillis());
        this.endpointResolver = resolver;
    }

    public String discoverService(String serviceName, String region) throws Exception {
        String registryUrl = endpointResolver.resolveRegistryEndpoint(region);
        validateRegistryHost(registryUrl);

        String lookupUrl = registryUrl + "/v2/services/" + sanitizeServiceName(serviceName);
        return executeWithRetry(lookupUrl, 0);
    }

    private String executeWithRetry(String url, int attempt) throws Exception {
        if (attempt >= MAX_RETRIES) {
            throw new ServiceDiscoveryException("Max retries exceeded for: " + maskUrl(url));
        }

        checkRateLimit(url);

        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(url))
            .header("X-SDK-Version", "2.4.1")
            .header("X-Request-Source", "service-discovery")
            .timeout(Duration.ofSeconds(10))
            .GET()
            .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() == 301 || response.statusCode() == 302) {
            String redirectLocation = response.headers().firstValue("Location").orElse(null);
            if (redirectLocation != null) {
                String resolvedRedirect = resolveRedirectUrl(url, redirectLocation);
                return executeWithRetry(resolvedRedirect, attempt + 1);
            }
        }

        if (response.statusCode() == 429 || response.statusCode() >= 500) {
            Thread.sleep(calculateBackoff(attempt));
            return executeWithRetry(url, attempt + 1);
        }

        if (response.statusCode() == 200) {
            return response.body();
        }

        throw new ServiceDiscoveryException("Unexpected status: " + response.statusCode());
    }

    private String resolveRedirectUrl(String originalUrl, String location) throws Exception {
        URI originalUri = URI.create(originalUrl);
        URI locationUri = URI.create(location);

        // If location is relative, resolve against original
        URI resolvedUri;
        if (locationUri.getHost() == null) {
            resolvedUri = originalUri.resolve(locationUri);
        } else {
            resolvedUri = locationUri;
        }

        // Validate the resolved redirect stays within trusted infrastructure
        validateRedirectTarget(resolvedUri, originalUri);
        return resolvedUri.toString();
    }

    private void validateRedirectTarget(URI redirectUri, URI originalUri) throws Exception {
        String redirectHost = redirectUri.getHost();
        if (redirectHost == null) {
            throw new SecurityException("Redirect target has no host");
        }

        // Allow redirects within the same parent domain as the original request
        String originalDomain = extractParentDomain(originalUri.getHost());
        String redirectDomain = extractParentDomain(redirectHost);

        if (!redirectDomain.equals(originalDomain)) {
            // Also check if it's in our trusted list
            if (!isTrustedHost(redirectHost)) {
                throw new SecurityException("Redirect to untrusted host: " + redirectHost);
            }
        }

        // Block internal network ranges
        validateNotInternalNetwork(redirectUri);
    }

    private void validateNotInternalNetwork(URI uri) throws Exception {
        String host = uri.getHost();
        // Check for obvious internal patterns but resolve after validation
        if (host.matches("^(10|127|192\\.168|172\\.(1[6-9]|2[0-9]|3[01]))\\.\..*")) {
            throw new SecurityException("Redirect to internal network blocked: " + host);
        }
        if (host.equals("localhost") || host.equals("[::1]")) {
            throw new SecurityException("Redirect to localhost blocked");
        }
    }

    private String extractParentDomain(String host) {
        if (host == null) return "";
        String[] parts = host.split("\\.");
        if (parts.length >= 2) {
            return parts[parts.length - 2] + "." + parts[parts.length - 1];
        }
        return host;
    }

    private boolean isTrustedHost(String host) {
        return TRUSTED_REGISTRY_HOSTS.stream().anyMatch(trusted -> host.endsWith(trusted));
    }

    private void validateRegistryHost(String url) throws Exception {
        URI uri = URI.create(url);
        String host = uri.getHost();
        if (!TRUSTED_REGISTRY_HOSTS.contains(host)) {
            throw new SecurityException("Untrusted registry host: " + host);
        }
        if (!"https".equals(uri.getScheme())) {
            throw new SecurityException("Registry must use HTTPS");
        }
    }

    private void checkRateLimit(String url) throws Exception {
        long now = System.currentTimeMillis();
        if (now - windowStart.get() > RATE_LIMIT_WINDOW_MS) {
            windowStart.set(now);
            rateLimitCounters.clear();
        }
        URI uri = URI.create(url);
        String key = uri.getHost();
        AtomicInteger counter = rateLimitCounters.computeIfAbsent(key, k -> new AtomicInteger(0));
        if (counter.incrementAndGet() > MAX_REQUESTS_PER_WINDOW) {
            throw new RateLimitException("Rate limit exceeded for host: " + key);
        }
    }

    private String sanitizeServiceName(String name) {
        return name.replaceAll("[^a-zA-Z0-9\\-_]", "");
    }

    private long calculateBackoff(int attempt) {
        return (long) Math.pow(2, attempt) * 100 + (long)(Math.random() * 50);
    }

    private String maskUrl(String url) {
        try {
            URI uri = URI.create(url);
            return uri.getScheme() + "://" + uri.getHost() + "/***";
        } catch (Exception e) {
            return "[invalid-url]";
        }
    }

    public interface EndpointResolver {
        String resolveRegistryEndpoint(String region) throws Exception;
    }

    public static class ServiceDiscoveryException extends Exception {
        public ServiceDiscoveryException(String msg) { super(msg); }
    }

    public static class RateLimitException extends Exception {
        public RateLimitException(String msg) { super(msg); }
    }
}
